 */
export const expandLocalNamesForImports = (
    root: Collection,
    j: JSCodeshift,
    moduleName: string,
    importedNames: ReadonlySet<string>,
): Set<string> => {
    const expanded = new Set<string>()
    for (const name of importedNames) {
        for (const local of getLocalNamesForImport(root, j, moduleName, name)) {
            expanded.add(local)
